using System; using QueryPlanning; using System.Collections.Generic; class Program { static void Main() { var problem = new QueryProblem(10, new List<TableSpec> { new TableSpec("a", 500, 3, new List<IndexSpec>()), new TableSpec("b", 600, 3, new List<IndexSpec>()) }, new List<PredicateSpec>(), new List<JoinSpec> { new JoinSpec("a", "b", 10) }); var mj = CostModel.ValidateAndCost(problem, new QueryPlan(new PlanNode("mergeJoin", Left: new PlanNode("tableScan", TableId: "a"), Right: new PlanNode("tableScan", TableId: "b")))); var hj = CostModel.ValidateAndCost(problem, new QueryPlan(new PlanNode("hashJoin", Left: new PlanNode("tableScan", TableId: "a"), Right: new PlanNode("tableScan", TableId: "b")))); var nl = CostModel.ValidateAndCost(problem, new QueryPlan(new PlanNode("nestedLoop", Left: new PlanNode("tableScan", TableId: "a"), Right: new PlanNode("tableScan", TableId: "b")))); Console.WriteLine("MJ Cost: " + mj.Metrics?.TotalCost); Console.WriteLine("HJ Cost: " + hj.Metrics?.TotalCost); Console.WriteLine("NL Cost: " + nl.Metrics?.TotalCost); } }
